`apps/web/src/api-client.ts` `fetchGreeting` — 3-level nesting for error mapping (not-ok → 400 check → body read → emptyName check). Rule 3.3: push that branching into a leaf helper, keep parent near straight-line.

```ts
async function toGreetingError(response: Response): Promise<GreetingServiceError> {
	if (response.status === 400) {
		const emptyNameMessage = readEmptyNameMessage(await readJsonBody(response));
		if (emptyNameMessage !== undefined) {
			return { code: 'EMPTY_NAME', message: emptyNameMessage };
		}
	}
	return { code: 'UPSTREAM_FAILURE', message: 'The greeting service rejected the request.' };
}

export async function fetchGreeting({ apiUrl, fetcher = fetch, name }: { ... }) {
	const endpoint = new URL('/api/greet', apiUrl);
	endpoint.searchParams.set('name', name);

	const response = await tryAsync(
		() => fetcher(endpoint, { cache: 'no-store' }),
		(): GreetingServiceError => ({ code: 'UPSTREAM_FAILURE', message: 'The greeting service is unavailable.' }),
	);
	if (isErr(response)) return response;

	if (!response.value.ok) {
		return err(await toGreetingError(response.value));
	}

	const message = readMessage(await readJsonBody(response.value));
	return message === undefined
		? err({ code: 'INVALID_UPSTREAM_RESPONSE', message: 'The greeting service returned an invalid response.' })
		: ok(message);
}
```

`readMessage`, `readEmptyNameMessage`, `readJsonBody` stay as-is (already leaf-level, fine). Net: `fetchGreeting` body drops one nesting level, error-shape decision now owned by one named helper instead of inline in the main flow.

